insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_131'
from (values
('127.880.d.5.A',3,'Before pulling a crease in a quarter panel, Marcus grinds the paint off a four-inch band around the damage with a 36-grit disc. He is:','["removing paint from the damaged area of a body panel", "only washing the panel", "masking the panel", "adding paint"]'::jsonb,0,'Strip the damaged area.','original'),
('127.880.d.5.A',4,'A coating-removal step before metal work is mainly done to:','["use up abrasives", "expose bare metal so the damage can be read and the repair bonds well", "add weight", "make the panel look shiny"]'::jsonb,1,'Bare metal shows damage.','original'),
('127.880.d.5.B',3,'After rough-shaping a fender, Priya drags her palm over it and sights along it with a bright light to find waves. She is:','["adding primer", "painting the fender", "identifying and repairing surface irregularities on a damaged body panel", "ignoring waves"]'::jsonb,2,'Check the contour.','original'),
('127.880.d.5.B',4,'A low spot is usually found with:','["a wrench", "a tire gauge", "a paint gun", "a flexible file or hand feel and then corrected before filler"]'::jsonb,3,'Locate lows first.','original'),
('127.880.d.5.C',3,'Using a spoon dolly behind a door skin, Jess taps the ridge around a dent and then lightly planishes the center. She is demonstrating:','["hammer and dolly techniques for dent repair", "welding", "spraying", "masking"]'::jsonb,0,'Dolly work.','original'),
('127.880.d.5.C',4,'With the hammer off-dolly, the technician is striking:','["the center of the dolly", "the high area beside the dolly to lower it without stretching", "the primer", "the glass"]'::jsonb,1,'Off-dolly lowers highs.','original'),
('127.880.d.5.D',3,'A technician heats a small oil-canned spot on a hood to dull cherry red and quenches it with a damp rag to tighten the metal. She is performing:','["painting", "cold shrinking", "heat shrinking of a stretched panel area", "polishing"]'::jsonb,2,'Heat then cool.','original'),
('127.880.d.5.D',4,'When heat shrinking, the technician must watch the heat to avoid:','["painting the panel", "cleaning the panel", "cooling the panel", "burning or warping the surrounding panel"]'::jsonb,3,'Control the heat.','original'),
('127.880.d.5.E',3,'Instead of using a torch, Dani works a stretched section with a hammer and dolly in a pattern so the metal tightens. She is performing:','["cold shrinking of a stretched panel area", "masking", "welding", "heat shrinking"]'::jsonb,0,'Hammer shrinking.','original'),
('127.880.d.5.E',4,'Compared with heat shrinking, cold shrinking is often favored on panels because it:','["needs no tools", "avoids the paint and metal damage heat can cause", "is much hotter", "uses more fuel"]'::jsonb,1,'No heat risk.','original'),
('127.880.d.5.F',3,'A student scuffs a repaired area, cleans it, mixes filler and cream hardener to a uniform color and spreads a thin coat. She is:','["polishing clear", "mixing paint", "identifying, preparing and applying body filler", "sanding primer"]'::jsonb,2,'Filler steps.','original'),
('127.880.d.5.F',4,'Filler should be spread in thin layers because thick layers can:','["stick better", "improve strength", "cure instantly", "crack, shrink or fail to cure properly"]'::jsonb,3,'Thin coats.','original'),
('127.880.d.5.G',3,'After curing, Omar shapes the filler with 80-grit on a long block, then moves to 180 and 240 before primer. He is:','["rough sanding and finish sanding body filler for primer", "stripping the filler", "washing the filler", "painting the filler"]'::jsonb,0,'Progressive grits.','original'),
('127.880.d.5.G',4,'A long sanding block is used on large panels to:','["dry the filler", "keep the contour flat and avoid waves", "add waves", "save paper"]'::jsonb,1,'Block sanding.','original'),
('127.880.d.5.H',3,'A technician learns that aluminum should be worked with dedicated tools, kept away from steel dust and shaped with care because it work-hardens. She is determining:','["the oil change", "the proper paint color", "the proper metal finishing techniques for aluminum", "the tire pressure"]'::jsonb,2,'Aluminum technique.','original'),
('127.880.d.5.H',4,'Using steel abrasives on aluminum after grinding steel can lead to:','["shinier metal", "stronger metal", "faster drying", "galvanic corrosion from embedded steel particles"]'::jsonb,3,'Avoid cross-contamination.','original'),
('127.880.d.5.I',3,'A technician checks the manufacturer''s guidance for filler on an aluminum fender, then uses a filler approved for aluminum. She is determining:','["the proper application of body filler to aluminum", "paint only", "no filler is allowed ever", "any filler works"]'::jsonb,0,'Use the approved filler.','original'),
('127.880.d.5.I',4,'Before applying filler to aluminum, the surface should be:','["painted red", "cleaned and mechanically prepared with aluminum-safe abrasives", "coated with water", "left oily"]'::jsonb,1,'Clean and prep.','original'),
('127.880.d.6.A',3,'A customer''s driver window won''t go up. The technician checks the switch, the motor and the regulator inside the door. She is:','["washing the door", "painting the window", "inspecting, adjusting, repairing or replacing window systems", "ignoring the problem"]'::jsonb,2,'Window system.','original'),
('127.880.d.6.A',4,'A window that makes a grinding noise and moves crookedly in its track likely has a:','["new tire", "full tank", "clean filter", "damaged or off-track regulator"]'::jsonb,3,'Regulator failure.','original'),
('127.880.d.6.B',3,'A technician replaces a torn door weatherstrip and checks that the seal makes even contact all around. She is:','["inspecting, adjusting, removing and reinstalling body sealing systems such as weatherstripping", "painting the door", "ignoring leaks", "guessing"]'::jsonb,0,'Sealing systems.','original'),
('127.880.d.6.B',4,'A door seal that has lost its resilience is likely to cause:','["quiet cabins", "wind noise and water leaks", "less wear", "dry carpets"]'::jsonb,1,'Seals keep out wind and water.','original'),
('127.880.d.6.C',3,'A technician inspects the run channels and the glass of a door and finds the felt strips worn so the glass rattles. She is:','["guessing", "painting", "inspecting, adjusting, repairing or replacing run channels and glass related to door window operation", "avoiding repair"]'::jsonb,2,'Run channels.','original'),
('127.880.d.6.C',4,'Worn glass run channels can cause:','["faster windows", "better fit", "quieter doors", "glass that rattles, binds or doesn''t seal"]'::jsonb,3,'Channel wear.','original'),
('127.880.d.6.D',3,'A technician lines up a soft top''s frame, checks its hydraulic pump and aligns the latch pins so the top closes evenly. She is:','["inspecting, removing, reinstalling and aligning convertible tops and related mechanisms", "guessing", "painting", "ignoring mechanisms"]'::jsonb,0,'Convertible top.','original'),
('127.880.d.6.D',4,'If a convertible top does not seat evenly against the windshield header, the likely cause is:','["clean glass", "misalignment of the frame or latches", "a full tank", "new wipers"]'::jsonb,1,'Alignment issue.','original'),
('127.880.d.7.A',3,'A student reads the code stamped inside a bumper cover, such as PP or TPO, to determine the type of plastic. She is:','["identifying glass", "identifying paint", "identifying the types of plastics used in automotive applications", "identifying tires"]'::jsonb,2,'Plastic ID.','original'),
('127.880.d.7.A',4,'Stamped codes like >PP+EPDM< on a plastic part tell a technician:','["the price", "the shop''s address", "the paint color", "the material, so the correct repair and adhesion method can be chosen"]'::jsonb,3,'Material codes.','original'),
('127.880.d.7.B',3,'A student washes a bumper cover with soap and water, then wipes it with a plastic-safe cleaner before sanding. She is:','["cleaning and preparing the surface of plastic parts", "ignoring prep", "painting the part", "gluing the part"]'::jsonb,0,'Clean plastic.','original'),
('127.880.d.7.B',4,'An adhesion promoter is sprayed on bare plastic to:','["remove color", "help primer and paint stick to the surface", "dry the plastic", "cool the plastic"]'::jsonb,1,'Promote adhesion.','original'),
('127.880.d.7.C',3,'A technician repairs a cracked flexible bumper cover using a plastic welder and reinforcing mesh. She is:','["guessing", "painting", "repairing rigid, semi-rigid or flexible plastic panels", "ignoring cracks"]'::jsonb,2,'Plastic repair.','original'),
('127.880.d.7.C',4,'For some plastics, a technician may choose adhesive repair instead of welding because:','["adhesives are weaker", "heat always works", "welding is easier on every plastic", "the material may not weld well with heat"]'::jsonb,3,'Match method to material.','original'),
('127.880.d.7.D',3,'A technician cuts out a damaged section of a fiberglass fender and feathers the edges for a repair patch. She is:','["removing or repairing damaged areas from rigid exterior composite panels", "painting", "guessing", "avoiding repair"]'::jsonb,0,'Composite repair.','original'),
('127.880.d.7.D',4,'When repairing fiberglass, a technician wears a respirator and gloves because dust and resin can:','["help healing", "irritate the lungs and skin", "clean the air", "cool the shop"]'::jsonb,1,'Protect yourself.','original'),
('127.880.d.7.E',3,'A technician removes a bonded composite door skin, cleans off old adhesive and installs a new skin with the specified adhesive, while aligning the supports. She is:','["painting", "guessing", "replacing bonded rigid exterior composite body panels, including straightening or aligning panel supports", "ignoring supports"]'::jsonb,2,'Replace composites.','original'),
('127.880.d.7.E',4,'After bonding a new composite panel, the technician should allow:','["no cure time", "water exposure at once", "instant painting", "the adhesive to cure for the specified time before further work"]'::jsonb,3,'Respect the cure.','original'),
('127.880.d.8.A',3,'Before the estimator can see all of the damage, a technician removes the bumper cover and the inner liner. She is:','["preparing the vehicle for inspection by providing access to damaged areas", "painting the car", "washing the car", "ignoring damage"]'::jsonb,0,'Provide access.','original'),
('127.880.d.8.A',4,'Providing access to hidden areas is important because it:','["hides the damage", "reveals damage not visible from the outside", "delays the estimate", "adds paint"]'::jsonb,1,'Hidden damage.','original'),
('127.880.d.8.B',3,'An estimator studies the points of impact and the direction of force to decide whether to pull, section or replace the rail. She is:','["guessing", "ignoring damage", "analyzing damage to determine the appropriate methods for overall repair", "painting"]'::jsonb,2,'Damage analysis.','original'),
('127.880.d.8.B',4,'The direction of impact matters in damage analysis because it:','["picks the radio", "determines paint color", "sets the tire size", "shows how force traveled through the structure"]'::jsonb,3,'Force path.','original'),
('127.880.d.8.C',3,'A technician looks over the rails, rocker panels and pillars for kinks, cracks and buckles. She is performing:','["a visual inspection of structural components and members", "a wash", "a paint job", "an alignment"]'::jsonb,0,'Structure inspection.','original'),
('127.880.d.8.C',4,'A kink in a frame rail indicates:','["a clean rail", "structural damage that must be repaired per the OEM procedure", "a paint issue", "cosmetic damage only"]'::jsonb,1,'Rails matter.','original'),
('127.880.d.8.D',3,'A technician mounts a vehicle on a measuring system and compares reference points to the manufacturer''s data. She is:','["painting", "ignoring data", "identifying structural damage using measuring tools and equipment", "guessing"]'::jsonb,2,'Measure structure.','original'),
('127.880.d.8.D',4,'A measurement that differs from the specification by more than the allowed tolerance means:','["the paint is bad", "the car is perfect", "the tires are worn", "the structure is out of position and needs correction"]'::jsonb,3,'Tolerance check.','original'),
('127.880.d.8.E',3,'A technician inspects a fender, a hood and a door for dents, misaligned gaps and scratches. She is performing:','["a visual inspection of non-structural components and members", "an alignment", "a weld", "a wash"]'::jsonb,0,'Bolt-on panels.','original'),
('127.880.d.8.E',4,'Non-structural panels include parts that:','["form the frame", "can be bolted or unbolted without altering the vehicle''s frame", "hold the engine", "carry the crash load"]'::jsonb,1,'Bolt-on.','original'),
('127.880.d.8.F',3,'After inspection, an estimator writes down which panels will be replaced, the materials they are made of and which procedures will be needed. She is determining:','["the paint color", "the customer''s age", "the parts, components, material types and procedures necessary for a proper repair", "the tire size"]'::jsonb,2,'Repair plan.','original'),
('127.880.d.8.F',4,'If a damaged panel is aluminum, the estimator must plan for:','["steel tools only", "no special plan", "wood tools", "aluminum-specific tools and procedures"]'::jsonb,3,'Material-specific.','original'),
('127.880.d.8.G',3,'An estimator checks the paint for scratches, chips and fading and decides if the whole panel or only the damaged area needs refinishing. She is:','["identifying the type and condition of the finish and determining if refinishing is required", "ignoring paint", "guessing", "polishing"]'::jsonb,0,'Finish evaluation.','original'),
('127.880.d.8.G',4,'A color code on the vehicle''s data plate is used to:','["set the oil type", "match the correct paint formula", "set tire pressure", "choose a radio"]'::jsonb,1,'Paint code.','original'),
('127.880.d.8.H',3,'A technician finds a bent control arm, a cracked headlight harness and a leaking radiator after a front-end collision. She is:','["guessing", "painting", "identifying suspension, electrical and mechanical component physical damage", "ignoring parts"]'::jsonb,2,'Mechanical damage.','original'),
('127.880.d.8.H',4,'A bent suspension part after a collision is dangerous because it can affect:','["paint color", "seat comfort", "radio volume", "steering and alignment"]'::jsonb,3,'Safety-critical.','original'),
('127.880.d.8.I',3,'A technician reviews a deployed airbag, a tensioned seat belt and a damaged impact sensor. She is:','["identifying safety systems physical damage", "ignoring safety", "guessing", "painting"]'::jsonb,0,'SRS damage.','original'),
('127.880.d.8.I',4,'After airbags have deployed, the technician should:','["ignore them", "replace the deployed parts and related sensors per OEM procedures", "tape them up", "reuse the bags"]'::jsonb,1,'Replace SRS.','original'),
('127.880.d.8.J',3,'An estimator notes a cracked dash pad, a torn seat and a damaged console after a collision. She is:','["ignoring the interior", "guessing", "identifying interior component damage", "painting"]'::jsonb,2,'Interior damage.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_131'
from (values
('127.880.d.8.J',4,'Interior damage is listed on an estimate so that it:','["is hidden", "is painted over", "is ignored", "is repaired or replaced and billed correctly"]'::jsonb,3,'Document the interior.','original'),
('127.880.d.8.K',3,'A technician notes that an aftermarket spoiler, a lift kit and a roof rack were damaged in the crash. She is:','["identifying damage to add-on accessories and modifications", "guessing", "ignoring accessories", "painting"]'::jsonb,0,'Aftermarket parts.','original'),
('127.880.d.8.K',4,'Aftermarket accessories damaged in a collision are listed separately because:','["they add no cost", "they may not be covered under the same policy", "they are always free", "they cannot be repaired"]'::jsonb,1,'Separate coverage.','original'),
('127.880.d.8.L',3,'A technician lists the structural bolts, torque-to-yield fasteners and airbag modules that cannot be reused after a collision. She is:','["ignoring parts", "painting", "identifying single or one-time use components", "listing reusable tools"]'::jsonb,2,'One-time use.','original'),
('127.880.d.8.L',4,'Torque-to-yield bolts should be replaced after removal because they:','["never wear", "improve with reuse", "are free", "stretch when tightened and cannot be reliably reused"]'::jsonb,3,'Stretch bolts.','original'),
('127.880.d.9.A',3,'A service writer records the owner''s name, phone, insurance carrier and claim number at the start of a repair file. She is:','["locating and recording customer and vehicle owner information", "ignoring the customer", "guessing", "painting"]'::jsonb,0,'Customer data.','original'),
('127.880.d.9.A',4,'Customer information on an estimate must be handled with care because it is:','["not needed", "private and should be protected", "useless", "public"]'::jsonb,1,'Protect privacy.','original'),
('127.880.d.9.B',3,'An estimator reads the 17-character VIN on the dash to confirm country of origin, make, model and model year. She is:','["reading a tire code", "reading a paint code", "locating and recording vehicle identification number information", "reading the odometer"]'::jsonb,2,'VIN.','original'),
('127.880.d.9.B',4,'The tenth character of a VIN usually shows the vehicle''s:','["owner''s name", "engine oil", "paint code", "model year"]'::jsonb,3,'VIN position 10.','original'),
('127.880.d.9.C',3,'An estimator checks the trim level, the paint code and any installed accessories on the build sheet. She is:','["identifying and recording vehicle options, including trim level, paint code, accessories and modifications", "ignoring options", "guessing", "painting"]'::jsonb,0,'Options matter.','original'),
('127.880.d.9.C',4,'Trim level matters in estimating because it:','["sets the radio", "affects part numbers and pricing", "sets oil type", "sets tire pressure"]'::jsonb,1,'Price depends on trim.','original'),
('127.880.d.9.D',3,'An estimator notes that the vehicle has front, side and curtain airbags and a belt pretensioner, since they may need replacement. She is:','["guessing", "painting", "identifying the safety systems", "ignoring them"]'::jsonb,2,'Safety systems.','original'),
('127.880.d.9.D',4,'Airbag and restraint systems are noted on an estimate because they:','["reduce cost", "add color", "are optional", "are critical to occupant safety and may need to be replaced"]'::jsonb,3,'Note SRS.','original'),
('127.880.d.9.E',3,'An estimator knows that ''R&I'' means remove and install, ''R&R'' means remove and replace and ''O/H'' means overhaul. She is applying:','["appropriate estimating and parts terminology", "random words", "guesswork", "slang"]'::jsonb,0,'Estimating terms.','original'),
('127.880.d.9.E',4,'On an estimate, ''R&R'' next to a bumper cover means the part will be:','["only painted", "removed and replaced with a new or used part", "only washed", "only repaired"]'::jsonb,1,'R&R.','original'),
('127.880.d.9.F',3,'An estimator lists operations in a logical order: teardown, repair, replace, refinish, reassembly. She is:','["painting first", "guessing", "determining and applying the appropriate estimating sequence", "ignoring order"]'::jsonb,2,'Sequence.','original'),
('127.880.d.9.F',4,'Following an estimating sequence helps prevent:','["a complete estimate", "accurate pricing", "extra paperwork", "missed operations and overlapping labor charges"]'::jsonb,3,'Avoid missed items.','original'),
('127.880.d.9.G',3,'An estimator opens a procedure page in the estimating guide to see what operations are included in a fender replacement. She is:','["utilizing estimating guide procedure pages", "ignoring the guide", "guessing", "painting"]'::jsonb,0,'Procedure pages.','original'),
('127.880.d.9.G',4,'Procedure pages help an estimator avoid:','["accurate estimates", "charging twice for tasks already included in a labor time", "complete notes", "saving time"]'::jsonb,1,'Included operations.','original'),
('127.880.d.9.H',3,'An estimator uses a database to find the labor time to replace a quarter panel in hours. She is:','["painting", "guessing", "estimating labor time for operations", "ignoring time"]'::jsonb,2,'Labor time.','original'),
('127.880.d.9.H',4,'A labor time of 4.5 hours at $60 per hour comes to:','["$135", "$64.50", "$450", "$270"]'::jsonb,3,'4.5 × 60 = 270.','original'),
('127.880.d.9.I',3,'An estimator applies a higher rate for structural repair and a different rate for refinish work. She is:','["selecting appropriate labor rates for each operation such as structural, non-structural, mechanical and refinish", "ignoring rates", "using one rate for all", "guessing"]'::jsonb,0,'Different rates.','original'),
('127.880.d.9.I',4,'Structural repair often has a higher labor rate because it requires:','["less time", "specialized equipment and training", "no tools", "no skills"]'::jsonb,1,'Skill and equipment.','original'),
('127.880.d.9.J',3,'An estimator compares prices of OEM, aftermarket and recycled parts for a hood. She is:','["ignoring prices", "guessing", "selecting and pricing replacement parts such as OEM, alternative OEM, aftermarket and recycled", "painting"]'::jsonb,2,'Parts options.','original'),
('127.880.d.9.J',4,'A recycled (used) part is one that is:','["made of paper", "never installed", "brand new", "taken from another vehicle in good condition"]'::jsonb,3,'Recycled part.','original'),
('127.880.d.9.K',3,'An estimator adds charges for a pull-clamp setup and for masking a vehicle that aren''t included in the guide''s labor times. She is determining:','["labor time, prices and charges for non-included operations and miscellaneous items", "paint colors", "included times", "no extras"]'::jsonb,0,'Non-included.','original'),
('127.880.d.9.K',4,'Non-included operations are billed separately because they are:','["free", "additional work beyond the standard labor time", "not real", "part of the base time"]'::jsonb,1,'Not part of base time.','original'),
('127.880.d.9.L',3,'An estimator includes a hazardous waste disposal fee, shop supplies and an administrative fee on a repair order. She is:','["painting", "guessing", "determining additional material and charges such as environmental, administrative, shop and disposal fees", "ignoring fees"]'::jsonb,2,'Additional charges.','original'),
('127.880.d.9.L',4,'A hazardous waste fee is added to an estimate to cover:','["the customer''s coffee", "tire costs", "a free gift", "the cost of properly disposing of paint and solvent waste"]'::jsonb,3,'Disposal costs.','original'),
('127.880.d.9.M',3,'An estimator multiplies the paint hours by a materials rate to price primer, base and clear. She is:','["determining refinishing material and charges", "ignoring paint", "guessing", "washing"]'::jsonb,0,'Paint materials.','original'),
('127.880.d.9.M',4,'Paint material charges are typically based on:','["the radio type", "refinish labor hours times a materials rate", "the owner''s age", "the car''s weight"]'::jsonb,1,'Materials rate.','original'),
('127.880.d.9.N',3,'Before giving an estimate to the customer, a writer proofreads it against the vehicle''s damage notes and checks the math. She is:','["ignoring errors", "skipping review", "reviewing computer-assisted and manually written estimates and verifying that the information is correct", "guessing"]'::jsonb,2,'Verify the estimate.','original'),
('127.880.d.9.N',4,'A careful review of an estimate helps prevent:','["clarity", "accuracy", "trust", "errors that cost the shop or the customer money"]'::jsonb,3,'Errors cost.','original'),
('127.880.d.9.O',3,'An estimator adds time and material for applying seam sealer, cavity wax and weld-through primer on a repaired quarter panel. She is:','["identifying labor time and material charges for restoring corrosion protection", "ignoring rust protection", "painting", "guessing"]'::jsonb,0,'Corrosion protection charge.','original'),
('127.880.d.9.O',4,'Restoring corrosion protection after a structural repair is important to:','["shorten the repair", "protect the repair from rust over time", "add noise", "lower cost"]'::jsonb,1,'Rust prevention.','original'),
('127.880.d.9.P',3,'An estimator compares a $9,800 repair bill to a car''s $8,500 market value to decide whether the vehicle is a total loss. She is:','["ignoring cost", "painting", "determining the approximate vehicle retail value compared to the repair cost", "guessing"]'::jsonb,2,'Total loss analysis.','original'),
('127.880.d.9.P',4,'A vehicle is generally considered a total loss when the repair cost:','["is under $50", "is zero", "is very small", "exceeds a set percentage of the vehicle''s value, as set by the insurer or state"]'::jsonb,3,'Total loss threshold.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
